/* ==UserStyle==
@name           Showdown - Surf sheets
@namespace      dasmins.showdown.vfx
@version        1.0.0
@description    Surf plays these hand-made sprite sheets (needs the pin-controls userscript, --surf-sheets: 1 in the main style).
@author         dasmins
==/UserStyle== */
@-moz-document domain("play.pokemonshowdown.com") {

:root {
    /* frames, frames per second, sheet columns, frame width, frame height, near feet x y, far feet x y (in the
       640x410 window the sheets were drawn for), impact time in ms, window width, window height */
    --surf-sheet-info: "45 20 8 320 205 226 358 370 216 1300 640 410";
    --surf-sheet-out-behind: url("data:image/png;base64,");
    --surf-sheet-out-between: url("data:image/png;base64,");
    --surf-sheet-out-front: url("data:image/png;base64,");
    --surf-sheet-in-behind: url("data:image/png;base64,");
    --surf-sheet-in-between: url("data:image/png;base64,");
    --surf-sheet-in-front: url("data:image/png;base64,");
  }

}
